// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {FlashGovernanceArbiter} from "../src/FlashGovernanceArbiter.sol";

contract InvMutTest is Test {
    FlashGovernanceArbiter c;

    function setUp() public {
        c = new FlashGovernanceArbiter(address(new __InvMutHandleStub()));
    }

    function testFuzz_property(address user, uint64 unlockDelay) public {
        // Assume a non-zero user address and avoid address(this) collisions.
        vm.assume(user != address(0));
        vm.assume(user != address(c));
        vm.assume(user != address(this));

        // Seed the pending flash decision via the public state variable setter path.
        // configureFlashGovernance is onlySuccessfulProposal; approved is true if configured == false.
        // endConfiguration() must be called to make onlySuccessfulProposal restrictive.
        // We deliberately keep configured == false so onlySuccessfulProposal passes broadly,
        // then configure a decision, then set the timestamp exactly to unlockTime.
        // unlockDelay is bounded to a wide admissible positive range.
        uint256 delay = bound(uint256(unlockDelay), 0, type(uint64).max);
        address asset = address(new __InvMutAsset());
        uint256 amount = 1;

        c.configureFlashGovernance(asset, amount, delay, false);

        // Seed the pending decision for `user` by pranking as a governed caller.
        // setGoverned requires onlySuccessfulProposal; since configured == false this passes.
        address[] memory governables = new address[](1);
        bool[] memory isGoverned = new bool[](1);
        governables[0] = user;
        isGoverned[0] = true;
        c.setGoverned(governables, isGoverned);

        // Actually create the pending decision by calling assertGovernanceApproved through the governed user.
        // The asset transferFrom succeeds on our stub asset.
        vm.prank(user);
        c.assertGovernanceApproved(user, address(c), true);

        // Read back the pending decision's unlockTime.
        (uint256 pAmount, uint256 pUnlockTime, , ) = c.pendingFlashDecision(address(c), user);
        vm.assume(pAmount > 0);

        // Warp exactly to the unlock timestamp.
        vm.warp(pUnlockTime);

        // At exactly unlockTime, reference must reject withdrawal (strict <), buggy allows (<=).
        bool ok;
        vm.prank(user);
        try c.withdrawGovernanceAsset(address(c), asset) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: at exactly the unlock timestamp, withdrawal must NOT succeed.
        assertTrue(!ok, "withdrawal succeeded exactly at unlockTime; should only be allowed strictly after");
    }
}

